package android.content
open class Context { open val applicationContext: Context get() = this; open fun getSharedPreferences(name: String, mode: Int): SharedPreferences = prefs; companion object { const val MODE_PRIVATE = 0; private val prefs = MemoryPrefs() } }
interface SharedPreferences { fun getString(key: String, defValue: String?): String?; fun edit(): Editor; interface Editor { fun putString(key: String, value: String?): Editor; fun remove(key: String): Editor; fun commit(): Boolean; fun apply() { commit() } } }
private class MemoryPrefs : SharedPreferences { private val values = mutableMapOf<String,String>(); override fun getString(key:String, defValue:String?)=values[key]?:defValue; override fun edit():SharedPreferences.Editor = object:SharedPreferences.Editor { override fun putString(key:String,value:String?)=apply { if(value==null) values.remove(key) else values[key]=value }; override fun remove(key:String)=apply { if(key!=null) values.remove(key) }; override fun commit()=true } }
